function validate(input) {
  const [{ Users = [], Transactions = [] }] = input;
  const accounts = new Set(), names = new Set(), transfers = new Set();
  for (const [account, name] of Users) {
    if (account === null) return 'Every user needs an account.';
    if (accounts.has(account)) return `account ${account} appears twice in Users.`;
    accounts.add(account);
    if (name === null) return `Account ${account} needs a name.`;
    const key = String(name).toLowerCase();
    if (names.has(key)) return `Two users are named ${name}.`;
    names.add(key);
  }
  for (const [id, account, amount, date] of Transactions) {
    if (id === null) return 'Every transaction needs a trans_id.';
    if (transfers.has(id)) return `trans_id ${id} appears twice in Transactions.`;
    transfers.add(id);
    if (account === null) return `Transaction ${id} needs an account.`;
    if (amount === null) return `Transaction ${id} needs an amount.`;
    if (date === null) return `Transaction ${id} needs a date.`;
  }
  return null;
}

