function generate(rand, size) {
  const pick = list => list[Math.floor(rand() * list.length)];
  const small = size === 'small';
  const pool = ['Alice', 'Bob', 'Charlie', 'Dana', 'Eve', 'Farid'];
  // Amounts around the 10000 threshold, so balances land just under, exactly on and just over it.
  const amounts = small ? [-4000, -3000, -1, 1, 1000, 3000, 5000, 6000, 7000, 10000, 10001] : [-5000, -2000, 1000, 3000, 5000, 7000, 10000];
  const dates = ['2020-08-01', '2020-08-07', '2020-09-01', '2020-09-02', '2020-09-12'];
  const userCount = small ? Math.floor(rand() * 6) : 500;
  const Users = [];
  for (let i = 0; i < userCount; i++) Users.push([900001 + i, small ? pool[i] : `User${i + 1}`]);
  const transferCount = small ? Math.floor(rand() * 9) : 2000;
  const Transactions = [];
  for (let id = 1; id <= transferCount; id++) {
    // Now and then a transaction names an account with no user; it must not be reported.
    const account = userCount === 0 || rand() < 0.1 ? 900099 : 900001 + Math.floor(rand() * userCount);
    Transactions.push([id, account, pick(amounts), pick(dates)]);
  }
  return [{ Users, Transactions }];
}
